      margin: 0;
      font-family: Inter, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
      color: var(--ink);
      background: var(--bg);
      line-height: 1.45;
    }
    .wrap { max-width: 1200px; margin: 0 auto; padding: 28px; }
    .hero {
      background: linear-gradient(120deg, #0f172a, #1e3a8a 55%, #0ea5e9);
      color: #fff; border-radius: 14px; padding: 26px;
      box-shadow: 0 10px 30px rgba(2,6,23,.22);
    }
    h1 { margin: 0 0 8px; font-size: 1.9rem; }
    .subtitle { margin: 0; opacity: .93; }
    .kpi-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:12px; margin-top:18px; }
    .kpi { background: rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.2); border-radius:10px; padding:12px; }
    .kpi .label { font-size:.78rem; opacity:.9; text-transform:uppercase; letter-spacing:.03em; }
    .kpi .val { font-size:1.35rem; font-weight:700; margin-top:6px; }
    section { margin-top: 20px; }
    .card { background:var(--card); border:1px solid var(--border); border-radius:12px; padding:16px; }
    h2 { margin:0 0 10px; font-size:1.25rem; }
    h3 { margin:8px 0; font-size:1rem; }
    .grid2 { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
    .grid3 { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
    table { width:100%; border-collapse: collapse; font-size:.9rem; }
    th,td { border-bottom:1px solid var(--border); padding:8px; text-align:left; }
    th { background:#f8fafc; }
    .muted { color: var(--muted); }
    .tag { display:inline-block; padding:2px 8px; border-radius:999px; font-size:.75rem; }
    .tag.good{background:#dcfce7;color:#166534;} .tag.warn{background:#fef3c7;color:#92400e;} .tag.bad{background:#fee2e2;color:#991b1b;}
    .recommendations li { margin: 7px 0; }
    @media (max-width:900px){ .grid2,.grid3{grid-template-columns:1fr;} }
  </style>
</head>
<body>
  <div class="wrap">
    <div class="hero">
      <h1>Global Smartwatch Secondary Market Analysis — Q1 2026</h1>
      <p class="subtitle">Data-driven resale intelligence for sourcing, pricing, and inventory decisions across Apple, Garmin, and Samsung listings.</p>
      <div class="kpi-grid" id="hero-kpis"></div>
    </div>

    <section class="card">
      <h2>Market Overview & Listing Composition</h2>
      <div class="grid3" id="overview-cards"></div>
      <div class="grid2" style="margin-top:12px;">
        <div>
          <h3>Brand Composition</h3>
          <canvas id="brandMix" height="220"></canvas>
        </div>
        <div>
          <h3>Condition Mix</h3>
          <canvas id="conditionMix" height="220"></canvas>
        </div>
      </div>
      <p class="muted" id="overview-text"></p>
    </section>

    <section class="card">
      <h2>Brand-Level Pricing & Value Retention</h2>
      <div class="grid2">
        <div>
          <canvas id="brandMedian" height="220"></canvas>
        </div>
        <div>
          <canvas id="brandRange" height="220"></canvas>
        </div>
      </div>
      <h3 style="margin-top:14px;">Brand Price Statistics</h3>
      <table id="brand-table"></table>
    </section>

    <section class="card">
      <h2>Geographic Pricing Arbitrage</h2>
      <div class="grid2">
        <div>
          <h3>Country Price Differential vs Brand Median</h3>
          <canvas id="geoArb" height="260"></canvas>
        </div>
        <div>
          <h3>Geographic Price Spread by Brand</h3>
          <canvas id="geoSpread" height="260"></canvas>
        </div>
      </div>
      <p class="muted" id="geo-text"></p>
      <table id="geo-table"></table>
    </section>

    <section class="card">
      <h2>Case Size & Price Premium Analysis</h2>
      <div class="grid2">
        <div><canvas id="caseCorr" height="230"></canvas></div>
        <div><canvas id="sizePremium" height="230"></canvas></div>
      </div>
      <table id="size-table"></table>
    </section>

    <section class="card">
      <h2>Power Seller Behavior & Pricing Patterns</h2>
      <div class="grid3" id="power-kpis"></div>
      <div class="grid2" style="margin-top:10px;">
        <div><canvas id="powerPricing" height="230"></canvas></div>
        <div><canvas id="powerMix" height="230"></canvas></div>
      </div>
      <table id="power-table"></table>
    </section>

    <section class="card">
      <h2>Strategic Recommendations</h2>
      <ol class="recommendations" id="reco-list"></ol>
    </section>
  </div>

<script>
const data = REPLACE_ANALYSIS_JSON;
const focusBrands = ['Apple','Garmin','Samsung'];
const fmt = n => (n==null || Number.isNaN(n)) ? '—' : '$' + Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
const pct = n => (n==null || Number.isNaN(n)) ? '—' : (n>=0?'+':'') + Number(n).toFixed(1) + '%';

const brandStats = data.brand_stats.filter(d=>focusBrands.includes(d.Brand));
const geoSpread = data.geo_spread.filter(d=>focusBrands.includes(d.Brand));
const geoBC = data.geo_brand_country.filter(d=>focusBrands.includes(d.Brand));
const sizePremium = data.size_premium.filter(d=>focusBrands.includes(d.Brand));
const powerBrand = data.power_brand_price.filter(d=>focusBrands.includes(d.Brand));
const powerMix = data.power_brand_mix.filter(d=>focusBrands.includes(d.Brand));
const newUsed = data.new_used_premium.filter(d=>focusBrands.includes(d.Brand));

const medianLeader = [...brandStats].sort((a,b)=>b.median-a.median)[0];
const biggestSpread = [...geoSpread].sort((a,b)=>b.spread-a.spread)[0];

document.getElementById('hero-kpis').innerHTML = `
  <div class="kpi"><div class="label">Total Listings</div><div class="val">${data.rows.toLocaleString()}</div></div>
  <div class="kpi"><div class="label">Median Leader</div><div class="val">${medianLeader.Brand} (${fmt(medianLeader.median)})</div></div>
  <div class="kpi"><div class="label">Max Geographic Spread</div><div class="val">${biggestSpread.Brand} (${fmt(biggestSpread.spread)})</div></div>
  <div class="kpi"><div class="label">Power Seller Concentration</div><div class="val">${data.power.top5pct_listing_share_pct.toFixed(1)}%</div></div>
`;

document.getElementById('overview-cards').innerHTML = `
  <div class="card"><h3>Total Listings</h3><div style="font-size:1.4rem;font-weight:700;">${data.rows.toLocaleString()}</div><div class="muted">Across ${data.countries} countries and ${data.unique_sellers.toLocaleString()} sellers.</div></div>
  <div class="card"><h3>Brand Concentration</h3><div style="font-size:1.4rem;font-weight:700;">${((data.brands.Apple||0)/data.rows*100).toFixed(1)}% Apple</div><div class="muted">Apple dominates listing supply; Garmin and Samsung form the secondary pool.</div></div>
  <div class="card"><h3>Condition Signal</h3><div style="font-size:1.4rem;font-weight:700;">${((data.conditions.New||0)/data.rows*100).toFixed(1)}% New</div><div class="muted">Used share: ${((data.conditions.Used||0)/data.rows*100).toFixed(1)}%.</div></div>
`;

document.getElementById('overview-text').textContent = `Market composition is concentrated in Apple listings (${(data.brands.Apple/data.rows*100).toFixed(1)}%), with a New-to-Used mix of ${(data.conditions.New/data.rows*100).toFixed(1)}% vs ${(data.conditions.Used/data.rows*100).toFixed(1)}%. This baseline implies that inventory strategy should differentiate between brand-led demand and condition-led margin.`;

new Chart(document.getElementById('brandMix'), {type:'doughnut',data:{labels:Object.keys(data.brands),datasets:[{data:Object.values(data.brands),backgroundColor:['#2563eb','#0ea5e9','#14b8a6','#94a3b8','#cbd5e1']}]},options:{plugins:{legend:{position:'bottom'}}}});
new Chart(document.getElementById('conditionMix'), {type:'bar',data:{labels:Object.keys(data.conditions),datasets:[{label:'Listings',data:Object.values(data.conditions),backgroundColor:'#2563eb'}]},options:{plugins:{legend:{display:false}},scales:{x:{ticks:{maxRotation:50,minRotation:40}}}}});
new Chart(document.getElementById('brandMedian'), {type:'bar',data:{labels:brandStats.map(d=>d.Brand),datasets:[{label:'Median Price',data:brandStats.map(d=>d.median),backgroundColor:['#2563eb','#0ea5e9','#14b8a6']}]},options:{plugins:{legend:{display:false}}}});
new Chart(document.getElementById('brandRange'), {type:'bar',data:{labels:brandStats.map(d=>d.Brand),datasets:[{label:'Min',data:brandStats.map(d=>d.min),backgroundColor:'#93c5fd'},{label:'Max',data:brandStats.map(d=>d.max),backgroundColor:'#1d4ed8'}]},options:{}});

document.getElementById('brand-table').innerHTML = `<tr><th>Brand</th><th>Count</th><th>Mean</th><th>Median</th><th>Min</th><th>Max</th><th>Std Dev</th></tr>` + brandStats.map(d=>`<tr><td>${d.Brand}</td><td>${d.count.toLocaleString()}</td><td>${fmt(d.mean)}</td><td><b>${fmt(d.median)}</b></td><td>${fmt(d.min)}</td><td>${fmt(d.max)}</td><td>${fmt(d.std)}</td></tr>`).join('');

const arbTop = [];
for (const b of focusBrands) {
  const rows = geoBC.filter(r=>r.Brand===b);
  const med = brandStats.find(x=>x.Brand===b).median;
  rows.forEach(r=>arbTop.push({key:`${b} — ${r.Country}`,delta:r.median_price-med,brand:b,country:r.Country,median_price:r.median_price,brand_median:med}));
}
arbTop.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));
const top15 = arbTop.slice(0,15);
new Chart(document.getElementById('geoArb'), {type:'bar',data:{labels:top15.map(d=>d.key),datasets:[{label:'Delta vs Brand Median (USD)',data:top15.map(d=>d.delta),backgroundColor:top15.map(d=>d.delta>=0?'#dc2626':'#16a34a')}]},options:{indexAxis:'y',plugins:{legend:{display:false}}}});
new Chart(document.getElementById('geoSpread'), {type:'bar',data:{labels:geoSpread.map(d=>d.Brand),datasets:[{label:'Spread',data:geoSpread.map(d=>d.spread),backgroundColor:['#2563eb','#0ea5e9','#14b8a6']}]},options:{plugins:{legend:{display:false}}}});

document.getElementById('geo-text').textContent = `${biggestSpread.Brand} shows the largest country-level median spread (${fmt(biggestSpread.spread)}), indicating the strongest arbitrage dispersion. Positive bars identify likely resale destinations; negative bars indicate potential sourcing markets.`;
document.getElementById('geo-table').innerHTML = `<tr><th>Brand</th><th>Country</th><th>Country Median</th><th>Brand Median</th><th>Delta</th></tr>` + top15.map(d=>`<tr><td>${d.brand}</td><td>${d.country}</td><td>${fmt(d.median_price)}</td><td>${fmt(d.brand_median)}</td><td><span class="tag ${d.delta>0?'bad':'good'}">${fmt(d.delta)}</span></td></tr>`).join('');

new Chart(document.getElementById('caseCorr'), {type:'bar',data:{labels:['Overall',...focusBrands],datasets:[{label:'Correlation (Case Size vs Price)',data:[data.case_corr_overall,...focusBrands.map(b=>data.case_corr_brand[b])],backgroundColor:'#0ea5e9'}]},options:{plugins:{legend:{display:false}},scales:{y:{min:-1,max:1}}}});
new Chart(document.getElementById('sizePremium'), {type:'bar',data:{labels:sizePremium.map(d=>d.Brand),datasets:[{label:'Large vs Small Median Premium %',data:sizePremium.map(d=>d.premium_pct),backgroundColor:sizePremium.map(d=>d.premium_pct>=0?'#16a34a':'#dc2626')}]},options:{plugins:{legend:{display:false}}}});
document.getElementById('size-table').innerHTML = `<tr><th>Brand</th><th>Small (&lt;45mm) Median</th><th>Large (&ge;45mm) Median</th><th>Premium %</th></tr>` + sizePremium.map(d=>`<tr><td>${d.Brand}</td><td>${fmt(d['Small (<45mm)'])}</td><td>${fmt(d['Large (>=45mm)'])}</td><td>${pct(d.premium_pct)}</td></tr>`).join('');

document.getElementById('power-kpis').innerHTML = `
  <div class="card"><h3>Top 5% Sellers</h3><div style="font-size:1.35rem;font-weight:700;">${data.power.top5pct_sellers}</div><div class="muted">of ${data.unique_sellers.toLocaleString()} sellers</div></div>
  <div class="card"><h3>Listing Share</h3><div style="font-size:1.35rem;font-weight:700;">${data.power.top5pct_listing_share_pct.toFixed(1)}%</div><div class="muted">controlled by top 5% sellers</div></div>
  <div class="card"><h3>Power Threshold</h3><div style="font-size:1.35rem;font-weight:700;">≥ ${data.power.threshold_min_listings} listings</div><div class="muted">minimum volume in top tier</div></div>
`;
new Chart(document.getElementById('powerPricing'), {type:'bar',data:{labels:powerBrand.map(d=>d.Brand),datasets:[{label:'Power Seller Median',data:powerBrand.map(d=>d['Power seller (top 5%)']),backgroundColor:'#1d4ed8'},{label:'Long Tail Median',data:powerBrand.map(d=>d['Long tail (95%)']),backgroundColor:'#93c5fd'}]},options:{}});
const pmLabels = [...new Set(powerMix.map(d=>d.Brand))];
const tierNames = ['Power seller (top 5%)','Long tail (95%)'];
new Chart(document.getElementById('powerMix'), {type:'bar',data:{labels:pmLabels,datasets:tierNames.map((t,i)=>({label:t,data:pmLabels.map(b=>{const r=powerMix.find(x=>x.Brand===b && x.seller_tier===t); return r?r.share_pct:0;}),backgroundColor:i? '#0ea5e9':'#2563eb'}))},options:{scales:{x:{stacked:false},y:{beginAtZero:true,max:100}}}});
document.getElementById('power-table').innerHTML = `<tr><th>Brand</th><th>Power Seller Median</th><th>Long Tail Median</th><th>Delta %</th></tr>` + powerBrand.map(d=>`<tr><td>${d.Brand}</td><td>${fmt(d['Power seller (top 5%)'])}</td><td>${fmt(d['Long tail (95%)'])}</td><td>${pct(d.delta_pct)}</td></tr>`).join('');

const reco = [
  `Prioritize ${biggestSpread.Brand} cross-border arbitrage lanes first: its country median spread is ${fmt(biggestSpread.spread)}, the widest among core brands, creating the largest sourcing-to-resale margin window.`,
  `Anchor baseline pricing to brand medians (Samsung ${fmt(brandStats.find(d=>d.Brand==='Samsung')?.median)}, Garmin ${fmt(brandStats.find(d=>d.Brand==='Garmin')?.median)}, Apple ${fmt(brandStats.find(d=>d.Brand==='Apple')?.median)}), then apply country-level delta adjustments rather than one global markup.`,
  `Use case size as a selective pricing lever, not a universal rule: overall case-size/price correlation is ${data.case_corr_overall.toFixed(2)} and brand-level effects diverge, so size premiums should be brand-specific.`,
  `Negotiate with power sellers for volume consistency but enforce brand-specific price guardrails: top 5% sellers control ${data.power.top5pct_listing_share_pct.toFixed(1)}% of listings, making them operationally important but potentially price-setting.`,
  `Apply condition-based bid ceilings by brand using measured New-vs-Used premiums: ${newUsed.map(d=>`${d.Brand} ${pct(d.premium_pct)}`).join(', ')}, preventing overpayment on inventory with weak condition uplift.`
];
document.getElementById('reco-list').innerHTML = reco.map(r=>`<li>${r}</li>`).join('');
</script>
</body>
</html>
